				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Triển khai Chiến lược và Kế hoạch</h2>				</div>
				</div>
		<div class="elementor-element elementor-element-e2b37b7 e-flex e-con-boxed e-con e-parent" data-id="e2b37b7" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-40eb104 elementor-widget elementor-widget-heading" data-id="40eb104" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
